#!/usr/bin/env python3
import sys,json,re,datetime
from collections import OrderedDict

HELP='''Usage: %s [-][ytjcrneikhv]\n\nConvert between YAML, TOML, JSON, and HCL.\nPreserves map order.\n\n-x[x]  Convert using stdin. Valid options:\n          -yj, -y = YAML to JSON (default)\n          -yy     = YAML to YAML\n          -yt     = YAML to TOML\n          -yc     = YAML to HCL\n          -tj, -t = TOML to JSON\n          -ty     = TOML to YAML\n          -tt     = TOML to TOML\n          -tc     = TOML to HCL\n          -jj     = JSON to JSON\n          -jy, -r = JSON to YAML\n          -jt     = JSON to TOML\n          -jc     = JSON to HCL\n          -cy     = HCL to YAML\n          -ct     = HCL to TOML\n          -cj, -c = HCL to JSON\n          -cc     = HCL to HCL\n-n     Do not covert inf, -inf, and NaN to/from strings (YAML or TOML only)\n-e     Escape HTML (JSON out only)\n-i     Indent output (JSON or TOML out only)\n-k     Attempt to parse keys as objects or numeric types (YAML out only)\n-h     Show this help message\n-v     Show version\n'''
def scalar(s):
 s=s.strip()
 if not s:return None
 if (s[:1] in "'\"" and s[-1:]==s[:1]):
  try:return json.loads(s) if s[0]=='"' else s[1:-1].replace("''", "'")
  except:return s[1:-1]
 if s in ('null','Null','NULL','~'):return None
 if s.lower() in ('true','false'):return s.lower()=='true'
 if s in ('.nan','.NaN','.NAN'):return 'NaN'
 if s.lower() in ('.inf','+.inf'):return 'Infinity'
 if s.lower()=='-.inf':return '-Infinity'
 if re.match(r'^[-+]?\d+$',s):
  try:return int(s)
  except:pass
 if re.match(r'^[-+]?(\d+\.\d*|\d*\.\d+)([eE][-+]?\d+)?$',s):
  try:return float(s)
  except:pass
 if s.startswith('[') and s.endswith(']'):
  return [scalar(x) for x in re.split(r'\s*,\s*',s[1:-1]) if x.strip()]
 return s
def yamlparse(x):
 lines=x.splitlines(); root=OrderedDict(); stack=[(-1,root)]; i=0
 while i<len(lines):
  raw=lines[i]; i+=1
  if not raw.strip() or raw.lstrip().startswith('#') or raw.strip() in ('---','...'):continue
  ind=len(raw)-len(raw.lstrip()); t=raw.strip()
  while stack[-1][0]>=ind:stack.pop()
  par=stack[-1][1]
  if t.startswith('- ' ) or t=='-':
   if not isinstance(par,list):continue
   v=t[1:].strip(); par.append(scalar(v)); continue
  if ':' not in t: continue
  k,v=t.split(':',1); k=k.strip().strip('"\''); v=v.strip()
  if not v and i<len(lines) and lines[i].strip().startswith('-'):
   obj=[]; par[k]=obj; stack.append((ind,obj)); continue
  if v in ('|','>'):
   vals=[]
   while i<len(lines) and len(lines[i])-len(lines[i].lstrip())>ind: vals.append(lines[i].strip());i+=1
   par[k]= ('\n'.join(vals)+'\n') if v=='|' else (' '.join(vals)+'\n'); continue
  if not v: obj=OrderedDict();par[k]=obj;stack.append((ind,obj))
  else: par[k]=scalar(v)
 return root
def parse_toml(x):
 root=OrderedDict(); cur=root
 for line in x.splitlines():
  line=line.split('#',1)[0].strip()
  if not line:continue
  m=re.match(r'\[\[([^]]+)\]\]',line)
  if m:
   key=m.group(1).strip(); cur=root
   for p in key.split('.'):
    if p not in cur:cur[p]=[]
    cur=cur[p]
   n=OrderedDict();cur.append(n);cur=n;continue
  m=re.match(r'\[([^]]+)\]',line)
  if m:
   cur=root
   for p in m.group(1).split('.'):
    cur=cur.setdefault(p,OrderedDict())
   continue
  if '=' in line:
   k,v=line.split('=',1);cur[k.strip().strip('"')]=scalar(v.strip())
 return root
def flat_yaml(v,n=0):
 out=[]; pad=' '*n
 if isinstance(v,dict):
  for k,x in v.items():
   if isinstance(x,dict):out.append(pad+str(k)+':');out+=flat_yaml(x,n+2)
   elif isinstance(x,list):out.append(pad+str(k)+':');out += [((' '*(n+2))+'- '+fmt(a)) for a in x]
   else:out.append(pad+str(k)+': '+fmt(x))
 elif isinstance(v,list):out += [pad+'- '+fmt(a) for a in v]
 return out
def fmt(v):
 if v is None:return 'null'
 if v is True:return 'true'
 if v is False:return 'false'
 if isinstance(v,(int,float)):return str(v).lower()
 if isinstance(v,list):return '['+', '.join(fmt(x) for x in v)+']'
 s=str(v)
 return s if re.match(r'^[A-Za-z_][\w.-]*$',s) and s.lower() not in ('true','false','null') else json.dumps(s,ensure_ascii=False)
def toml(v,prefix=''):
 out=[]
 if not isinstance(v,dict):return ''
 for k,x in v.items():
  if not isinstance(x,dict):out.append(str(k)+' = '+json.dumps(x,ensure_ascii=False) if isinstance(x,str) else str(k)+' = '+fmt(x))
 for k,x in v.items():
  if isinstance(x,dict):out+=['','['+('.'.join(filter(None,[prefix,k]))+']')]+toml(x,'.'.join(filter(None,[prefix,k]))).splitlines()
 return '\n'.join(out)
def hcl(v):
 if not isinstance(v,dict):return fmt(v)
 lines=[]
 for k,x in v.items():
  lines.append(json.dumps(str(k))+' = '+(hcl(x) if isinstance(x,dict) else fmt(x)));lines.append('')
 return '\n'.join(lines).rstrip()
def main():
 args=sys.argv[1:]; src='y';dst='j'; ind=False;esc=False; key=False; no=False
 if any(a=='-v' for a in args):print('v0.0.0');return 0
 if any(a=='-h' for a in args):print(HELP%sys.argv[0],end='');return 0
 for a in args:
  if not a.startswith('-') or a.startswith('--'):
   print(HELP%sys.argv[0],end='');print('Error: invalid flags specified: '+' '.join(a.lstrip('-')),file=sys.stdout);return 1
  for c in a[1:]:
   if c not in 'ytjcrneikhv':print(HELP%sys.argv[0],end='');print('Error: invalid flags specified: '+' '.join(a[1:]),file=sys.stdout);return 1
  s=a[1:];
  if len(s)>=2 and s[0] in 'ytjc' and s[1] in 'ytjc':src,dst=s[0],s[1]
  elif 'r' in s:src,dst='j','y'
  elif 'c' in s and len(s)==2:src,dst='h','j'
  elif 't' in s and len(s)==1:src,dst='t','j'
  elif 'y' in s and len(s)==1:src,dst='y','j'
  ind|='i' in s;esc|='e' in s;key|='k' in s;no|='n' in s
 data=sys.stdin.read()
 if not data:return 0
 try: val=json.loads(data,object_pairs_hook=OrderedDict) if src=='j' else (parse_toml(data) if src=='t' else yamlparse(data))
 except Exception as e: print('Error parsing %s: %s'%( {'j':'JSON','t':'TOML','y':'YAML','h':'HCL'}.get(src,src),e),file=sys.stderr);return 1
 if dst=='j':
  kw={'ensure_ascii':False};
  if ind:kw['indent']=2
  out=json.dumps(val,**kw,separators=None if ind else (',',':'))
  if esc:out=out.replace('<','\\u003c').replace('>','\\u003e').replace('&','\\u0026')
  print(out)
 elif dst=='y':print('\n'.join(flat_yaml(val))+'\n',end='')
 elif dst=='t':print(toml(val)+'\n',end='')
 else:print(hcl(val),end='')
 return 0
if __name__=='__main__':sys.exit(main())
